ST_PKI = "opt-sigrift-pki"
ST_PKI_OWNERS = ("0:0", "1500:1500")
ST_RP_ID = re.compile(r"[0-9]{8}T[0-9]{6}Z-[A-Za-z0-9._-]{1,40}-full(-[0-9]+)?\Z")
ST_FRAME_MAX = 1 << 20
ST_HEARTBEAT = 5.0
ST_SPACE_STEP = 64 << 20
ST_RATIO_MIN = 64 << 20
